/// <summary>
/// class <c>METTelemetrySOReadyForPricingEvent</c> is used to log event whenever the order processing status is updated as ready for pricing.
/// </summary>
internal final class METTelemetrySOReadyForPricingEvent extends ISMTelemetryBase
{
}

Method.Source:
/// <summary>
/// Initialize the class <c>METTelemetrySOReadyForPricingEvent</c>
/// </summary>
/// <returns> Instance of class <c>METTelemetrySOReadyForPricingEvent</c> </returns>
public static METTelemetrySOReadyForPricingEvent construct()
{
    return new METTelemetrySOReadyForPricingEvent();
}

/// <summary>
/// if the log level is set to information it will log the request and response data as wekk as there is an error
/// </summary>
/// <returns> a boolean value </returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// Add runtime telemetry property to application insights.
/// </summary>
/// <param name = "_salesTable"> instanse of table <c>_salesTable</c> </param>
public void addRunTimePropertyToAppinsights(SalesTable _salesTable,METSalesTable _metSalesTable)
{
    this.addRuntimeProperty(METTelemetryProperties::salesOrderNumber, _salesTable.SalesId);
    this.addRuntimeProperty(METTelemetryProperties::warehouseId,_salesTable.InventLocationId);
    this.addRuntimeProperty(METTelemetryProperties::orderReferenceNumber, _salesTable.CustomerRef);
    this.addRuntimeProperty(METTelemetryProperties::industryKey, _metSalesTable.IndustryKey);
    this.addRuntimeProperty(METTelemetryProperties::metcashSalesOrderType, _salesTable.METSalesOrderType);
    this.addRuntimeProperty(METTelemetryProperties::customerNumber, _salesTable.CustAccount);
    this.addRuntimeProperty(METTelemetryProperties::transmissionNumber, _metSalesTable.TransmissionNumber);
}
